/**
 * Column width guidelines for DvTable components
 *
 * These constants provide standardized column width ranges based on content type
 * to ensure consistency across tables and optimal user experience.
 */

/**
 * Content-based width categories
 */
var COLUMN_WIDTH_RANGES = {
  /** Short Text (Dates, Status Labels, IDs): 80-120px */
  SHORT: {
    MIN: 80,
    MAX: 120,
    DEFAULT: 100
  },
  /** Medium Text (Names, Titles, Short Descriptions): 150-250px */
  MEDIUM: {
    MIN: 150,
    MAX: 250,
    DEFAULT: 200
  },
  /** Long Text (Addresses, Notes, Descriptions): 250-400px (truncated) */
  LONG: {
    MIN: 250,
    MAX: 400,
    DEFAULT: 300
  },
  /** Numeric Data (Prices, Percentages, Counts): Right-aligned, sized per expected value length */
  NUMERIC: {
    MIN: 80,
    MAX: 150,
    DEFAULT: 100
  },
  /** Checkbox and selection columns */
  CHECKBOX: {
    MIN: 52,
    MAX: 52,
    DEFAULT: 52
  },
  /** Icon button columns */
  ICON_BUTTON: {
    MIN: 60,
    MAX: 80,
    DEFAULT: 70
  }
};

/**
 * Content type mapping for automatic width assignment
 */
var CONTENT_TYPE_WIDTHS = {
  /** Date fields, timestamps */
  DATE: COLUMN_WIDTH_RANGES.SHORT,
  /** Status badges, labels */
  STATUS: COLUMN_WIDTH_RANGES.SHORT,
  /** ID fields, codes */
  ID: COLUMN_WIDTH_RANGES.SHORT,
  /** Names, titles */
  NAME: COLUMN_WIDTH_RANGES.MEDIUM,
  /** Email addresses */
  EMAIL: COLUMN_WIDTH_RANGES.MEDIUM,
  /** Short descriptions */
  DESCRIPTION_SHORT: COLUMN_WIDTH_RANGES.MEDIUM,
  /** Long descriptions, notes, addresses */
  DESCRIPTION_LONG: COLUMN_WIDTH_RANGES.LONG,
  /** Numeric values, prices */
  NUMERIC: COLUMN_WIDTH_RANGES.NUMERIC,
  /** Percentages */
  PERCENTAGE: COLUMN_WIDTH_RANGES.NUMERIC,
  /** Counts, quantities */
  COUNT: COLUMN_WIDTH_RANGES.NUMERIC,
  /** Checkbox columns */
  CHECKBOX: COLUMN_WIDTH_RANGES.CHECKBOX,
  /** Icon button columns */
  ICON_BUTTON: COLUMN_WIDTH_RANGES.ICON_BUTTON
};

/**
 * Column width priority levels for space allocation
 */
var COLUMN_PRIORITY = {
  /** Critical data that should never be hidden */
  CRITICAL: 'critical',
  /** Important data that gets priority */
  HIGH: 'high',
  /** Standard priority */
  MEDIUM: 'medium',
  /** Can be compressed or hidden on smaller screens */
  LOW: 'low'
};

/**
 * Truncation behavior configuration settings for TruncatedText component
 *
 * @example
 * ```tsx
 * <TruncatedText
 *   text="Long text content"
 *   config={{
 *     strategy: TRUNCATION_SETTINGS.STRATEGY.TOOLTIP,
 *     threshold: TRUNCATION_SETTINGS.THRESHOLDS.TOOLTIP
 *   }}
 * />
 * ```
 */
var TRUNCATION_SETTINGS = {
  /** Character count thresholds for triggering truncation */
  THRESHOLDS: {
    /** Show tooltip for text longer than 25 characters */
    TOOLTIP: 25,
    /** Show popover for text longer than 50 characters */
    POPOVER: 50
  },
  /** Available truncation display strategies */
  STRATEGY: {
    /** Simple tooltip overlay on hover */
    TOOLTIP: 'tooltip',
    /** Rich popover with detailed content */
    POPOVER: 'popover',
    /** Native browser title attribute */
    NATIVE: 'native'
  }
};

export { COLUMN_PRIORITY, COLUMN_WIDTH_RANGES, CONTENT_TYPE_WIDTHS, TRUNCATION_SETTINGS };
